\begin{lemma}
\label{lemma-automorphism-inner}
Let $A$ be a finite central simple $k$-algebra. Any automorphism of $A$ is
inner. In particular, any automorphism of $\text{Mat}(n \times n, k)$
is inner.
\end{lemma}

