\begin{theorem}
\label{theorem-centralizer}
$A$를 $k$ 위의 유한 중심 단순 대수라 하고, $B$를 $A$의 단순
부분대수라 하자. 그러면 다음이 성립한다.
\begin{enumerate}
\item $A$ 안에서 $B$의 중심화자 $C$는 단순하다.
\item $[A : k] = [B : k][C : k]$이다.
\item $A$ 안에서 $C$의 중심화자는 $B$이다.
\end{enumerate}
\end{theorem}

source_expression:
\begin{theorem}
\label{theorem-centralizer}
Let $A$ be a finite central simple algebra over $k$, and let
$B$ be a simple subalgebra of $A$. Then
\begin{enumerate}
\item the centralizer $C$ of $B$ in $A$ is simple,
\item $[A : k] = [B : k][C : k]$, and
\item the centralizer of $C$ in $A$ is $B$.
\end{enumerate}
\end{theorem}

